import pandas as pd, numpy as np
pd.set_option('display.width',250); pd.set_option('display.max_columns',60); pd.set_option('display.max_rows',300)
tok=pd.read_csv('data/tokens.csv'); life=pd.read_csv('data/token_life.csv')
lp=life.groupby('mint').mc.max().rename('life_peak'); tok=tok.join(lp,on='mint'); tok['peak']=tok[['peak_mc_usd','life_peak']].max(axis=1)
tok['t']=pd.to_datetime(tok.launch_utc); tok=tok.sort_values('t')
print("tokens",len(tok),"creators",tok.creator.nunique(),"peak known",tok.peak.notna().sum())
for th in [20e3,50e3,100e3,500e3,1e6]: print(f"  launches reaching ${th/1e3:.0f}K: {(tok.peak>=th).sum()} ({(tok.peak>=th).mean()*100:.2f}%)")
print("  graduated:",tok.graduated.sum(), f"({tok.graduated.mean()*100:.2f}%)")
c=tok.groupby('creator').agg(n=('mint','size'),g=('graduated','sum'),p50=('peak',lambda s:(s>=50e3).sum()),p100=('peak',lambda s:(s>=100e3).sum()),best=('peak','max'),bundle=('bundle_pct','mean'),age=('creator_age_s','median'))
print("\nlaunches per creator:"); print(c.n.value_counts().sort_index().head(10).to_dict(), "max", c.n.max())
# does prior success predict? sequential: for each launch, creator's prior launches count and prior >=50K count
tok['prior_n']=tok.groupby('creator').cumcount()
tok['hit50']=(tok.peak>=50e3).astype(int); tok['hit100']=(tok.peak>=100e3).astype(int)
tok['prior_50']=tok.groupby('creator').hit50.transform(lambda s:s.shift().fillna(0).cumsum())
tok['prior_100']=tok.groupby('creator').hit100.transform(lambda s:s.shift().fillna(0).cumsum())
tok['prior_grad']=tok.groupby('creator').graduated.transform(lambda s:s.shift().fillna(0).cumsum())
def tab(g): return pd.Series({'launches':len(g),'hit50K':round(g.hit50.mean(),3),'hit100K':round(g.hit100.mean(),3),'hit500K':round((g.peak>=500e3).mean(),4),'grad':round(g.graduated.mean(),4)})
print("\nby creator's PRIOR launch count:"); print(tok.assign(b=pd.cut(tok.prior_n,[-1,0,1,2,4,9,1000])).groupby('b',observed=True).apply(tab))
print("\nby creator's PRIOR launches that hit $50K:"); print(tok.assign(b=pd.cut(tok.prior_50,[-1,0,1,2,1000])).groupby('b',observed=True).apply(tab))
print("\nby creator's PRIOR launches that hit $100K:"); print(tok.assign(b=pd.cut(tok.prior_100,[-1,0,1,2,1000])).groupby('b',observed=True).apply(tab))
print("\nby creator's PRIOR graduations:"); print(tok.assign(b=pd.cut(tok.prior_grad,[-1,0,1,2,1000])).groupby('b',observed=True).apply(tab))
print("\nfresh creator wallet (age) vs hit:"); print(tok.assign(b=pd.cut(tok.creator_age_s/86400,[-1,0.01,1,7,30,365,1e5])).groupby('b',observed=True).apply(tab))
print("\ncreator funded SOL:"); print(tok.assign(b=pd.cut(tok.creator_funded_sol,[-1,0,1,5,20,100,1e6])).groupby('b',observed=True).apply(tab))
print("\nTOP creators (>=2 launches) by $100K hits:"); print(c[c.n>=2].sort_values(['p100','g','best'],ascending=False).head(15).round(0))
print("\nTOP creators by graduations:"); print(c[c.g>=2].sort_values(['g','n']).tail(12).round(0))
